{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table andamen_db.maplemonk.andamen_db_Customer_Behavior_Analysis as With Pre_Base_Sales_Data as ( select *,CASE WHEN EXTRACT(MONTH FROM order_date::date) >= 4 THEN (EXTRACT(YEAR FROM order_date::date))+1 ELSE (EXTRACT(YEAR FROM order_date::date)) END AS financial_year from andamen_db.MAPLEMONK.andamen_db_sales_consolidated where not(lower(order_status) like \'%cancel%\' or lower(shipping_status) like \'%cancel%\' or lower(order_status) like \'%rto%\' or lower(shipping_status) like \'%rto%\' and lower(order_status) like \'%return%\' or lower(shipping_status) like \'%return%\') and customer_id_final is not null and lower(marketplace) like any (\'%shopify%\',\'%woocommerce%\', \'%magento%\') and reference_code in ( select reference_code from andamen_db.MAPLEMONK.andamen_db_sales_consolidated group by 1 having avg(ifnull(selling_price,0)) >= 1000 ) ) , Base_Years AS ( SELECT customer_id_final, min(financial_year) AS start_year FROM Pre_Base_Sales_Data GROUP BY 1 ), Recursive_Years AS ( SELECT customer_id_final, concat(start_year,\'-03-31\')::date as Order_date, start_year AS year FROM Base_Years UNION ALL SELECT customer_id_final, concat(year+1,\'-03-31\')::date as Order_date, year + 1 AS year FROM Recursive_Years WHERE year + 1 <= (CASE WHEN EXTRACT(MONTH FROM current_date::Date) >= 4 THEN (EXTRACT(YEAR FROM current_date::date))+1 ELSE (EXTRACT(YEAR FROM current_date::date)) END) ), Base_Sales_Data as ( ( Select CUSTOMER_ID_FINAL ,ACQUISITION_DATE ,FIRST_COMPLETE_ORDER_DATE ,MAPLE_MONK_ID_PHONE ,CUSTOMER_ID ,SHOP_NAME ,MARKETPLACE ,CHANNEL ,SOURCE ,ORDER_ID ,REFERENCE_CODE ,SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,PRODUCT_NAME ,CURRENCY ,CITY ,STATE ,ORDER_STATUS ,ORDER_DATE ,ORDER_TIMESTAMP ,QUANTITY ,GROSS_SALES_BEFORE_TAX ,DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE ,OMS_ORDER_STATUS ,SHIPPING_STATUS ,FINAL_SHIPPING_STATUS ,SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID ,AWB ,PAYMENT_GATEWAY ,PAYMENT_MODE ,COURIER ,DISPATCH_DATE ,DELIVERED_DATE ,DELIVERED_STATUS ,RETURN_FLAG ,RETURNED_QUANTITY ,RETURNED_SALES ,CANCELLED_QUANTITY ,DAYS_IN_SHIPMENT ,ACQUSITION_DATE ,SKU_CODE ,PRODUCT_NAME_FINAL ,PRODUCT_CATEGORY ,PRODUCT_SUB_CATEGORY ,COLLECTION ,SEASON ,LAUNCH_DATE ,WAREHOUSE ,PINCODE ,SOURCE_PINCODE ,DISPATCH_TAT ,CONFIRM_DATE ,QC_PASS_DATE ,PRINT_DATE ,EASYECOM_PRODUCTID ,NEW_CUSTOMER_FLAG ,NEW_CUSTOMER_FLAG_MONTH ,ACQUISITION_PRODUCT ,ACQUISITION_CHANNEL ,ACQUISITION_MARKETPLACE ,ORDER_DATE as Extra_ORDER_DATE ,1 as ACTIVE_FLAG ,financial_year as current_fy_Year from Pre_Base_Sales_Data ) UNION ALL ( Select CUSTOMER_ID_FINAL ,NULL AS ACQUISITION_DATE ,NULL AS FIRST_COMPLETE_ORDER_DATE ,NULL AS MAPLE_MONK_ID_PHONE ,NULL AS CUSTOMER_ID ,NULL AS SHOP_NAME ,NULL AS MARKETPLACE ,NULL AS CHANNEL ,NULL AS SOURCE ,NULL AS ORDER_ID ,NULL AS REFERENCE_CODE ,NULL AS SHIPPING_LAST_UPDATE_DATE ,NULL AS SKU ,NULL AS PRODUCT_ID ,NULL AS PRODUCT_NAME ,NULL AS CURRENCY ,NULL AS CITY ,NULL AS STATE ,NULL AS ORDER_STATUS ,null as ORDER_DATE ,NULL AS ORDER_TIMESTAMP ,NULL AS QUANTITY ,NULL AS GROSS_SALES_BEFORE_TAX ,NULL AS DISCOUNT ,NULL AS TAX ,NULL AS SHIPPING_PRICE ,NULL AS SELLING_PRICE ,NULL AS OMS_ORDER_STATUS ,NULL AS SHIPPING_STATUS ,NULL AS FINAL_SHIPPING_STATUS ,NULL AS SALEORDERITEMCODE ,NULL AS SALES_ORDER_ITEM_ID ,NULL AS AWB ,NULL AS PAYMENT_GATEWAY ,NULL AS PAYMENT_MODE ,NULL AS COURIER ,NULL AS DISPATCH_DATE ,NULL AS DELIVERED_DATE ,NULL AS DELIVERED_STATUS ,NULL AS RETURN_FLAG ,NULL AS RETURNED_QUANTITY ,NULL AS RETURNED_SALES ,NULL AS CANCELLED_QUANTITY ,NULL AS DAYS_IN_SHIPMENT ,NULL AS ACQUSITION_DATE ,NULL AS SKU_CODE ,NULL AS PRODUCT_NAME_FINAL ,NULL AS PRODUCT_CATEGORY ,NULL AS PRODUCT_SUB_CATEGORY ,NULL AS COLLECTION ,NULL AS SEASON ,NULL AS LAUNCH_DATE ,NULL AS WAREHOUSE ,NULL AS PINCODE ,NULL AS SOURCE_PINCODE ,NULL AS DISPATCH_TAT ,NULL AS CONFIRM_DATE ,NULL AS QC_PASS_DATE ,NULL AS PRINT_DATE ,NULL AS EASYECOM_PRODUCTID ,NULL AS NEW_CUSTOMER_FLAG ,NULL AS NEW_CUSTOMER_FLAG_MONTH ,NULL AS ACQUISITION_PRODUCT ,NULL AS ACQUISITION_CHANNEL ,NULL AS ACQUISITION_MARKETPLACE ,ORDER_DATE as Extra_ORDER_DATE ,0 as ACTIVE_FLAG ,year(order_date) as current_fy_Year from Recursive_Years where concat(CUSTOMER_ID_FINAL,year) not in (select distinct concat(CUSTOMER_ID_FINAL,financial_year) from Pre_Base_Sales_Data ) ) ) ,Churn_Previous_Purchase as ( Select ch.*,nch.Order_date as Previous_Churn_Order_Date from ( Select customer_id_final, current_fy_Year as Churn_PFY, from Base_Sales_Data where ACTIVE_FLAG = 0 ) ch left join ( select distinct customer_id_final ,current_fy_Year ,order_date::date as Order_date, from Base_Sales_Data where ACTIVE_FLAG = 1 )nch on ch.customer_id_final = nch.customer_id_final and ch.Churn_PFY > current_fy_Year qualify row_number() over(partition by ch.customer_id_final,ch.Churn_PFY order by Order_date desc) = 1 ) ,Previous_Purchase as ( Select distinct customer_id_final ,reference_code ,LAG(Order_date) OVER (PARTITION BY customer_id_final ORDER BY Order_date asc) AS Previous_Purchase_Date from ( select distinct customer_id_final, order_date::date as Order_date, reference_code from Base_Sales_Data where ACTIVE_FLAG = 1 ) ), Days_Calculations as ( select customer_id_final , min(order_date) aquisition_fy_date, (min(current_fy_Year)) aquisition_fy_Year, max(order_date) as Last_Purchase_Date, DATEDIFF(day, max(order_date), CURRENT_DATE) Days_from_last_purchase from Base_Sales_Data where ACTIVE_FLAG = 1 group by 1 ), No_Of_Orders as ( select * from ( select customer_id_final ,current_fy_Year FY ,COUNT(reference_code) OVER (PARTITION BY customer_id_final ORDER BY current_fy_Year ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) no_of_orders_fy from ( select distinct customer_id_final, current_fy_Year, reference_code from Base_Sales_Data ) ) qualify row_number() over(partition by customer_id_final,fy order by no_of_orders_fy desc ) = 1 ) select sc.*,aquisition_fy_date as aquisition_fy_date ,aquisition_fy_Year ,Last_Purchase_Date ,Days_from_last_purchase Days_from_last_purchase_current_date ,noo.no_of_orders_fy ,case when no_of_orders_fy = 1 then \'Single (1)\' when no_of_orders_fy in (2,3) then \'Repeat (2,3)\' when no_of_orders_fy in (4,5) then \'Loyal (4,5)\' when no_of_orders_fy > 5 then \'Champion (>5)\' end as FY_Loyalty_Segment ,pp.Previous_Purchase_Date ,datediff(\'day\',pp.Previous_Purchase_Date,sc.order_date) as Days_from_last_purchase ,case when ACTIVE_FLAG = 1 then DATEDIFF(DAY, sc.order_date, LEAST(concat(current_fy_Year,\'-03-31\')::date,current_date)) else DATEDIFF(DAY,cpp.Previous_Churn_Order_Date , LEAST(concat(current_fy_Year,\'-03-31\')::date,current_date)) end as days_from_Previous_Purchase ,case when days_from_Previous_Purchase < 365 then \'Active (<365)\' when days_from_Previous_Purchase < 453 then \'About to Dormant (<453)\' when days_from_Previous_Purchase < 543 then \'Dormant (<543)\' else \'Lost (>=543)\' end as FY_Retention_Segment ,div0(acq_spend,count(*) over(partition by sc.order_Date::Date,active_flag)) as acq_spend ,div0(RET_SPEND,count(*) over(partition by sc.order_Date::Date,active_flag)) as RET_SPEND ,datediff(\'day\',last_purchase_date,current_date) as last_purchase_days ,case when last_purchase_days < 7 then \'<7 Days\' when last_purchase_days < 30 then \'7-30 Days\' when last_purchase_days < 90 then \'30-90 Days\' when last_purchase_days < 180 then \'90-180 Days\' when last_purchase_days < 365 then \'180-365 Days\' else \'>=365\' end as Last_Purchase_Segment ,case when dense_rank() over(partition by sc.CUSTOMER_ID_FINAL order by sc.current_fy_Year asc) = 1 then \'new\' else \'repeat\' end as new_customer_flag_fy ,case when dense_rank() over(partition by sc.CUSTOMER_ID_FINAL order by sc.order_date::date asc) = 1 then \'new\' else \'repeat\' end as new_customer_flag_day ,case when dense_rank() over(partition by sc.CUSTOMER_ID_FINAL order by last_day(sc.order_date::date) asc) = 1 then \'new\' else \'repeat\' end as new_customer_flag_fy_month ,GROSS_MARGIN ,ifnull(selling_price,0) * ifnull(GROSS_MARGIN,0) as GROSS_MARGIN_VALUE ,CASE WHEN EXTRACT(MONTH FROM current_date::date) >= 4 THEN (EXTRACT(YEAR FROM current_date::date))+1 ELSE (EXTRACT(YEAR FROM current_date::date)) END AS current_Date_year from Base_Sales_Data sc left join Days_Calculations dc on sc.customer_id_final = dc.customer_id_final left join Previous_Purchase pp on sc.customer_id_final = pp.customer_id_final and sc.reference_code = pp.reference_code left join No_Of_Orders noo on noo.customer_id_final = sc.customer_id_final and noo.fy = sc.current_fy_Year left join Churn_Previous_Purchase cpp on cpp.customer_id_final = sc.customer_id_final and cpp.Churn_PFY = sc.current_fy_Year left join ( select date::date as date ,sum(ifnull(spend,0) * ifnull(acq_spend_share,1)) as acq_spend ,sum(ifnull(spend,0) * (1 - ifnull(acq_spend_share,1))) as ret_spend from andamen_db.MAPLEMONK.andamen_db_MARKETING_CONSOLIDATED mc left join ( select channel ,TO_DATE(START_DATE, \'DD-MON-YY\') AS START_DATE ,TO_DATE(END_Date, \'DD-MON-YY\') AS END_Date ,replace(MARKETING_SPEND_SHARE_ACQUSITION,\'%\',\'\') /100 as acq_spend_share from andamen_db.maplemonk.andamen_gs_retention_costs qualify row_number() over(partition by channel,START_DATE,END_Date order by 1) = 1 )acs on lower(acs.channel) = lower(mc.channel) and mc.date >= acs.START_DATE and mc.date <= acs.END_Date where lower(mc.channel) like any (\'%google%\',\'%facebook%\') group by 1 )mc on sc.order_date::date = mc.date::date and sc.active_flag = 1 left join ( select fy,replace(GROSS_MARGIN,\'%\',\'\') /100 GROSS_MARGIN from andamen_db.maplemonk.andamen_gs_fy_gross_margin qualify row_number() over(partition by fy order by 1) = 1 )gm on gm.fy = sc.current_fy_Year ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from andamen_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            